"""Build the pinned-snapshot Legendary/Mythical image roster and terrain reference.
Original artwork is fetched from the source URLs recorded in the bundled catalogue.
"""
import concurrent.futures,hashlib,json,shutil,urllib.request
from pathlib import Path
root=Path(__file__).resolve().parents[1];out=root/'docs/pokemon-preview/reference-assets';out.mkdir(parents=True,exist_ok=True)
c=json.loads((root/'src/workshop/pokemon/data/catalog.json').read_text());species={}
for p in c['forms']:
 if p['default'] or p['speciesId'] not in species:species[p['speciesId']]=p
rows=sorted((p for p in species.values() if p['legendary'] or p['mythical']),key=lambda p:p['speciesId'])
def fetch(p):
 dst=out/(str(p['speciesId'])+'.png')
 if not dst.exists():
  req=urllib.request.Request(p['image'],headers={'User-Agent':'RoleForge-Pokemon-Preview'})
  body=urllib.request.urlopen(req,timeout=60).read();assert body.startswith(b'\x89PNG');dst.write_bytes(body)
 return {'speciesId':p['speciesId'],'name':p['name'],'generation':p['generation'],'category':'legendary' if p['legendary'] else 'mythical','source':p['image'],'file':dst.name,'sha256':hashlib.sha256(dst.read_bytes()).hexdigest()}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:manifest=list(pool.map(fetch,rows))
(root/'docs/pokemon-preview/reference-art.json').write_text(json.dumps({'classificationSource':c['source'],'legendary':71,'mythical':23,'counting':'Unique species; alternate forms are not counted twice. Not an assertion of current-franchise completeness.','artwork':'Original Pokemon artwork mirrored by PokeAPI/sprites; not official hosting.','entries':manifest},ensure_ascii=False,indent=2)+'\n')
regions={1:'Kanto',2:'Johto',3:'Hoenn',4:'Sinnoh',5:'Unova',6:'Kalos',7:'Alola',8:'Galar / Hisui',9:'Paldea / Kitakami'}
base='../../src/workshop/pokemon/assets/battle/'
fields=[('grass','ทุ่งหญ้า'),('longgrass','หญ้าสูง'),('sand','ทราย / ชายหาด'),('water','ทะเล'),('pond','บ่อน้ำ'),('underwater','ใต้น้ำ'),('mountain','ภูเขา'),('cave','ถ้ำ'),('building','อาคาร'),('indoor-plain','สนามในอาคาร'),('indoor-1','สนามในอาคาร I'),('indoor-2','สนามในอาคาร II'),('indoor-gym','Gym'),('indoor-leader','Gym Leader'),('indoor-lorelei','Elite Four · Lorelei'),('indoor-bruno','Elite Four · Bruno'),('indoor-agatha','Elite Four · Agatha'),('indoor-lance','Elite Four · Lance'),('indoor-champion','Champion'),('indoor-link','Link Battle')]
def cards(kind,gens):
 text=''
 for gen in gens:
  mons=[r for r in manifest if r['category']==kind and r['generation']==gen]
  if not mons:continue
  text+=f'<div class="gen"><h3><b>GEN {gen}</b> {regions[gen]}</h3><span>{len(mons)} สายพันธุ์</span></div><div class="mons">'
  for m in mons:text+=f'<article><img src="reference-assets/{m["file"]}" alt="{m["name"]}" width="112" height="112"><small>#{m["speciesId"]:04d}</small><strong>{m["name"]}</strong></article>'
  text+='</div>'
 return text
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pokémon · Legendary roster & battle scenes</title><style>@font-face{font-family:Thai;src:url('../../assets/chat-fonts/noto-sans-thai.woff2')}@font-face{font-family:Latin;src:url('../../assets/chat-fonts/noto-sans-display.woff2')}*{box-sizing:border-box}body{margin:0;background:#e6edf2;color:#17384d;font:18px/1.6 Latin,Thai,system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:32px 28px}header{padding:15px 8px 30px}header small{font-size:12px;letter-spacing:2px;color:#bc4052}h1{font-size:38px;line-height:1.3;margin:12px 0}p{color:#617d8d;font-size:16px}.sheet{background:white;padding:36px;margin:0 0 32px;border:1px solid #c5d4df;border-radius:16px}.sheet h2{margin:0;font-size:28px;line-height:1.4}.sheet-header{border-bottom:3px solid #df5564;padding:0 0 18px;margin-bottom:24px;display:flex;justify-content:space-between;align-items:end;gap:20px}.sheet-header p{font-size:15px;margin:8px 0 0}.sheet-header>span{font-size:13px;color:#7a909d;text-align:right}.gen{display:flex;align-items:center;justify-content:space-between;margin:23px 0 12px}.gen h3{margin:0;font-size:20px;font-weight:600}.gen b{font-size:13px;padding:3px 8px;background:#eaf1f6;border-radius:4px;margin-right:8px}.gen>span{font-size:14px;color:#7e94a1}.mons{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.mons article{padding:10px 6px 12px;border:1px solid #e1e9ee;border-radius:11px;text-align:center;min-width:0;background:linear-gradient(#f7fafc,#fff)}.mons img{display:block;object-fit:contain;margin:auto;max-width:100%}.mons small{display:block;font-size:12px;color:#8498a5;line-height:1.7}.mons strong{display:block;font-size:18px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.footer{margin:24px 0 0;padding-top:15px;border-top:1px solid #dce5ea;font-size:12px;color:#8c9da7}.mythical .sheet-header{border-color:#a172c0}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.fields article{border:1px solid #d6e2e9;border-radius:10px;overflow:hidden;background:#f7fafb}.fields img{display:block;width:100%;height:auto;image-rendering:pixelated}.fields h3{margin:12px 14px 2px;font-size:17px;font-weight:600}.fields p{margin:0 14px 12px;font-size:12px}a{color:#216ead;text-underline-offset:4px}@media(max-width:700px){main{padding:20px 12px}h1{font-size:29px}.sheet{padding:20px 14px}.sheet h2{font-size:24px}.sheet-header{display:block}.sheet-header>span{display:block;text-align:left;margin-top:12px}.mons{grid-template-columns:repeat(2,1fr);gap:10px}.mons strong{font-size:17px}.gen h3{font-size:17px}.gen>span{font-size:12px}.fields{grid-template-columns:repeat(2,1fr);gap:10px}.fields h3{font-size:14px;margin:8px 10px 2px}.fields p{margin:0 10px 10px;font-size:10px}}</style><main><header><small>ROLEFORGE · POKÉMON PREVIEW</small><h1>ข้อมูลที่มีจริงใน Addon</h1><p>อิง snapshot PokeAPI ที่อยู่ในโปรเจคท์ · 1,025 สายพันธุ์ / 1,579 รายการฟอร์ม<br>รายชื่อนับสายพันธุ์ไม่ซ้ำ แยก Legendary กับ Mythical และไม่นับ Ultra Beast / Paradox เป็น Legendary เพิ่มเอง</p></header>'''
for sid,title,sub,kind,gens in [('legendary-1','Legendary Pokémon · 1 / 2','Gen 1–5 · 35 สายพันธุ์','legendary',range(1,6)),('legendary-2','Legendary Pokémon · 2 / 2','Gen 6–9 · 36 สายพันธุ์','legendary',range(6,10)),('mythical','Mythical Pokémon','แยกจาก Legendary · 23 สายพันธุ์','mythical',range(1,10))]:
 html+=f'<section class="sheet {kind}" id="{sid}" data-sheet="{sid}"><div class="sheet-header"><div><h2>{title}</h2><p>{sub}</p></div><span>71 Legendary + 23 Mythical<br>จากข้อมูลที่บันทึกใน Addon</span></div>'+cards(kind,gens)+'<div class="footer">Original Pokémon artwork · PokeAPI/sprites mirror · Classification: bundled PokeAPI snapshot. Images do not imply an unlocked encounter.</div></section>'
html+='<section class="sheet" data-sheet="terrains" id="terrains"><div class="sheet-header"><div><h2>20 สนามจาก Pokémon FireRed</h2><p>ภาพและ palette จากเกมต้นฉบับ · เลือกเองหรือเลือกตามสถานที่ในโรล</p></div><span>เปลี่ยนภาพสนามเท่านั้น<br>ยังไม่ได้เพิ่มระบบ Trainer / Gym battle</span></div><div class="fields">'
for key,title in fields:html+=f'<article><img src="{base}firered-{key}.png" alt="{title}" width="240" height="112"><h3>{title}</h3><p>FireRed · {key}</p></article>'
html+='</div><div class="footer">Decoded original FireRed tilemaps and palettes · Pinned pret/pokefirered mirror · Nintendo / Game Freak / Creatures / The Pokémon Company.</div></section><p><a href="reference-art.json">รายการพร้อมแหล่งภาพ</a> · <a href="https://github.com/pret/pokefirered/tree/ce6406d8c2eaf46d543c8a2606de0c3cb1951982/graphics/battle_terrain">แหล่งภาพสนามต้นฉบับเกม</a></p></main></html>'
(root/'docs/pokemon-preview/reference.html').write_text(html)
print('Built 71 Legendary + 23 Mythical reference portraits and 20 terrain sheet.')
